import json, time, urllib.request, urllib.error, sys
B="http://localhost:8080"
tok=None
log=[]
def req(path, method="GET"):
    global tok
    for attempt in range(200):
        h={}
        if path!="/token":
            if tok is None: tok=req("/token","POST")["token"]
            h["Authorization"]="Bearer "+tok
        r=urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None)
        try:
            with urllib.request.urlopen(r,timeout=30) as resp:
                body=resp.read()
                return json.loads(body)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors="replace")
            log.append((path,e.code,dict(e.headers),body[:200]))
            if e.code==404: return {"__404":True}
            if e.code==401 or e.code==403:
                tok=None; continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                try: w=float(ra)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                time.sleep(w+0.1); continue
            time.sleep(1)
        except Exception as ex:
            log.append((path,"exc",repr(ex),""))
            time.sleep(1)
    raise RuntimeError("failed "+path)
orders=[]; page=1; total=None
pages={}
while True:
    d=req(f"/orders?page={page}")
    pages[page]=d
    total=d["total_pages"]
    orders.append((page,d["items"]))
    print(page,len(d["items"]),d["next"],file=sys.stderr)
    if d["next"] is None: break
    page+=1
json.dump(orders,open("/tmp/work/orders.json","w"))
cust={}
ids={o["customer_id"] for _,it in orders for o in it}
for c in sorted(ids):
    cust[c]=req(f"/customers/{c}")
json.dump(cust,open("/tmp/work/cust.json","w"))
json.dump(log,open("/tmp/work/log.json","w"),indent=1)
print("pages",page,"total_pages",total,"customers",len(cust))
EOF
